preset.customCSS:
@import url("https://fonts.googleapis.com/css2?family=Noto+Serif+KR:wght@400;600;700&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 1rem .75rem;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtfan-font-size로 바꿉니다. */
.rtfan {
  --rtfan-bg-fill: transparent;
  --rtfan-blur: none;
  --rtfan-bg-edge: none;
  --rtfan-font-body: "Noto Serif KR", "Nanum Myeongjo", "Batang", serif;
  --rtfan-font-display: "Noto Serif KR", "Nanum Myeongjo", "Batang", serif;
  --rtfan-font-size: 16px;
  --rtfan-line-height: 1.85;
  --rtfan-para-gap: .9em;
  --rtfan-dialog-weight: 600;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtfan {
  --risu-font-family: var(--rtfan-font-body);
  --FontColorStandard: var(--rtfan-ink);
  --FontColorBold: var(--rtfan-ink);
  --FontColorItalic: var(--rtfan-muted);
  --FontColorItalicBold: var(--rtfan-muted);
  --FontColorQuote1: var(--rtfan-muted);
  --FontColorQuote2: var(--rtfan-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtfan-ink);
  font-family: var(--rtfan-font-body);
  font-size: var(--rtfan-font-size);
  line-height: var(--rtfan-line-height);
}
.rtfan, .rtfan *, .rtfan *::before, .rtfan *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtfan.rtfan { display: block; }
.rtfan__content {
  min-width: 0;
  color: var(--rtfan-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtfan__content .chattext {
  --tw-prose-code: var(--rtfan-ink);
  --tw-prose-pre-code: var(--rtfan-ink);
  --tw-prose-pre-bg: var(--rtfan-tint);
  max-width: none;
  color: var(--rtfan-ink);
  font-size: var(--rtfan-font-size) !important;
  line-height: var(--rtfan-line-height) !important;
}
.rtfan__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtfan-font-size);
  line-height: var(--rtfan-line-height);
}
.rtfan__content p { margin: 0 0 var(--rtfan-para-gap); }
.rtfan__content p:last-child { margin-bottom: 0; }
.rtfan__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtfan-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtfan-ink);
  font-family: var(--rtfan-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtfan__content h1 { font-size: calc(var(--rtfan-font-size) * 1.6); }
.rtfan__content h2 { font-size: calc(var(--rtfan-font-size) * 1.35); }
.rtfan__content h3 { font-size: calc(var(--rtfan-font-size) * 1.15); }
.rtfan__content :is(h4, h5, h6) { font-size: var(--rtfan-font-size); }
.rtfan__content strong { font-weight: 700; }
.rtfan__content em { color: var(--rtfan-muted); }
.rtfan__content mark[risu-mark="quote1"],
.rtfan__content mark[risu-mark="blockquote1"] { color: var(--rtfan-muted); background: transparent; }
.rtfan__content mark[risu-mark="quote2"],
.rtfan__content mark[risu-mark="blockquote2"] {
  color: var(--rtfan-dialog);
  font-weight: var(--rtfan-dialog-weight);
  background: transparent;
}
.rtfan__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtfan-line);
  color: var(--rtfan-muted);
}
.rtfan__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtfan__content li { margin: .25em 0; color: var(--rtfan-ink); }
.rtfan__content li::marker { color: var(--rtfan-muted); }
.rtfan__content a { color: var(--rtfan-accent); text-decoration: underline; }
.rtfan__content hr { border: 0; border-top: 1px solid var(--rtfan-line); margin: 1.5em 0; }
.rtfan__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtfan-ink);
  background: var(--rtfan-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtfan-font-size) * .88);
}
.rtfan__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtfan-ink);
  background: var(--rtfan-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtfan-font-size) * .88);
  line-height: 1.5;
}
.rtfan__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtfan__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtfan__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtfan-ink);
  border-bottom: 1px solid var(--rtfan-line);
  text-align: left;
  vertical-align: top;
}
.rtfan__content th { font-weight: 700; }
.rtfan__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtfan__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtfan-ink) !important;
  background: var(--rtfan-edit-bg) !important;
  border: 1px solid var(--rtfan-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtfan-font-size) !important;
  line-height: var(--rtfan-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtfan__footer {
  --risu-theme-textcolor2: var(--rtfan-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtfan__info, .rtfan__actions { min-width: 0; max-width: 100%; }
.rtfan__info > div, .rtfan__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtfan__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtfan__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtfan__footer button:hover { background: var(--rtfan-tint); }
.rtfan :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtfan-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtfan__portrait { overflow: hidden; background: var(--rtfan-tint); }
.rtfan__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtfan__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtfan-bg-fill);
  -webkit-backdrop-filter: var(--rtfan-blur);
  backdrop-filter: var(--rtfan-blur);
  box-shadow: var(--rtfan-bg-edge);
}

/* 구조: 판타지 */

.rtfan {
  max-width: 50rem;
  margin: 0 auto;
  padding: clamp(1.4rem, 4%, 2.2rem) clamp(1.3rem, 5%, 2.8rem) 1.2rem;
}
/* 양피지: 바탕 층에 얼룩과 고르지 않은 가장자리 */
.rtfan .rtfan__bg {
  background:
    radial-gradient(ellipse at 12% 8%, var(--rtfan-stain) 0, transparent 45%),
    radial-gradient(ellipse at 92% 96%, var(--rtfan-stain) 0, transparent 42%),
    radial-gradient(ellipse at 60% 40%, rgba(255, 255, 255, .06) 0, transparent 60%),
    var(--rtfan-paper);
  clip-path: polygon(0.6% 1.4%, 8% 0.3%, 19% 1.1%, 33% 0%, 47% 0.9%, 61% 0.2%, 74% 1.2%, 88% 0.1%, 99.4% 1%, 100% 9%, 99.2% 24%, 100% 41%, 99.3% 58%, 100% 74%, 99.1% 90%, 99.6% 98.8%, 90% 99.6%, 76% 98.9%, 62% 100%, 47% 99.1%, 33% 99.9%, 18% 98.8%, 6% 99.7%, 0.4% 98.6%, 0.9% 86%, 0% 70%, 0.8% 53%, 0% 37%, 0.7% 21%);
}
/* 모서리 장식: 카드 폭에 맞춰 크기가 바뀝니다 */
.rtfan::before, .rtfan::after {
  content: "✦";
  position: absolute;
  top: clamp(.4rem, 1.4%, .9rem);
  color: var(--rtfan-accent);
  font-size: clamp(.7rem, 1.6vw, 1.15rem);
  line-height: 1;
  pointer-events: none;
}
.rtfan::before { left: clamp(.5rem, 1.8%, 1.1rem); }
.rtfan::after { right: clamp(.5rem, 1.8%, 1.1rem); }
.rtfan__head { display: flex; align-items: center; gap: .9rem; margin-bottom: 1rem; padding-bottom: .7rem; border-bottom: 1px solid var(--rtfan-line); }
/* 밀랍 인장 */
.rtfan__portrait {
  flex: 0 0 auto;
  width: var(--rtfan-seal-w);
  aspect-ratio: 1;
  border-radius: 50%;
  border: clamp(2px, .5vw, 4px) solid var(--rtfan-seal);
  box-shadow: 0 0 0 clamp(2px, .45vw, 4px) var(--rtfan-seal-dark), 0 3px 8px var(--rtfan-shadow);
}
.rtfan { --rtfan-seal-w: clamp(3.2rem, 9%, 5rem); }
.rtfan--user { --rtfan-seal-w: clamp(2.6rem, 7%, 3.8rem); }
.rtfan__title { font-family: var(--rtfan-font-display); font-size: 1.25em; font-weight: 700; color: var(--rtfan-ink); }
.rtfan__suffix { color: var(--rtfan-muted); font-weight: 400; font-size: .85em; }
.rtfan--char .rtfan__content .chattext > p:first-child::first-letter {
  float: left;
  margin: .08em .12em 0 0;
  color: var(--rtfan-accent);
  font-family: var(--rtfan-font-display);
  font-size: 2.9em;
  line-height: .9;
  font-weight: 700;
}
.rtfan__footer { margin-top: .9rem; padding-top: .5rem; border-top: 1px dashed var(--rtfan-line); font-size: .85em; }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (황토) ── */
.rtfan {
  --rtfan-paper: #ecdcb6;
  --rtfan-stain: rgba(140, 95, 45, .16);
  --rtfan-ink: #3b2a18;
  --rtfan-muted: #7d6646;
  --rtfan-accent: #7c3a26;
  --rtfan-dialog: #5e2a18;
  --rtfan-seal: #8b3226;
  --rtfan-seal-dark: #5e2018;
  --rtfan-shadow: rgba(60, 35, 10, .28);
  --rtfan-line: #c4aa82;
  --rtfan-tint: #e2cfa6;
  --rtfan-edit-bg: #f4e7cb;
}
